"""Document recognized revisions from catalog metadata, without reading ROMs."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    document = json.loads((ROOT / "src/retrolarium_kit/core/profiles/repositories.json").read_text(encoding="utf-8"))
    lines = [
        "# Recognized ROM revisions",
        "",
        "Generated by `python tools/document_rom_revisions.py` from the pinned repository catalog.",
        "Hashes cover the complete file, including its container header. No ROM bytes are stored here.",
        "",
        "Supply your own matching dump. Different iNES or fwNES headers, interleaved `.smd`",
        "dumps and other revisions may have different hashes. Kit does not rewrite a ROM",
        "or normalize its header silently. A nonmatching image can be edited as a generic",
        "ROM project in Studio; automatic source setup requires a catalog match.",
        "",
        "| Game | Revision | SHA-256 of complete file |",
        "| --- | --- | --- |",
    ]
    for game, entry in document["games"].items():
        for revision in entry["revisions"]:
            lines.append(f"| {game} | {revision['name']} | `{revision['sha256']}` |")
    lines += [
        "",
        "The catalog records recognized revision names, rather than promising a",
        "particular ROM filename. Renaming a file does not change its recognition hash.",
        "",
    ]
    (ROOT / "docs/supported_roms.md").write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
